    local cell = loopView:NewListViewItem("Cell")
    ---@type UIActivityMidFestivalBossRankRewardCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.CrisisContract.Cell.ActivityCrisisContractRankingDescPopupCell")
    scr:Refresh(cellData)
    return cell
end

function ActivityCrisisContractRankingDescPopup:RefreshUI()
